import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import '../core/clinic_theme.dart';
import '../data/clinic_scope.dart';

/// Scribe — ambient documentation drafts. Drafts are generated by the
/// backend agent (`draft_encounter_chart`) and appear here for practitioner
/// review: read the SOAP sections, edit in mind, mark reviewed. The scribe
/// never finalizes a note itself (CONTEXT.md — "Grounding over generation").
class ScribePage extends StatelessWidget {
  const ScribePage({super.key});

  @override
  Widget build(BuildContext context) {
    final scope = context.watch<ClinicScope>();
    final encounters = scope.stream('encounters');

    if (encounters == null) {
      return const Center(child: CircularProgressIndicator(color: ClinicTheme.malachite));
    }

    return Padding(
      padding: const EdgeInsets.all(24),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Scribe', style: TextStyle(fontSize: 24, fontWeight: FontWeight.w800)),
          const Text(
            'Ambient drafts from exam conversations. Review, then mark reviewed — '
            'the draft never becomes the chart on its own.',
            style: TextStyle(color: ClinicTheme.textSecondary),
          ),
          const SizedBox(height: 24),
          Expanded(
            child: StreamBuilder<ClinicRows>(
              stream: encounters,
              builder: (context, snap) {
                final rows = snap.data ?? const [];
                if (rows.isEmpty) {
                  return const Card(
                    child: Padding(
                      padding: EdgeInsets.all(20),
                      child: Text(
                        'No encounters yet. Seed the demo world (backend/seed_clinic_demo.py) '
                        'or record an encounter — drafts from the scribe agent land here.',
                        style: TextStyle(color: ClinicTheme.textSecondary),
                      ),
                    ),
                  );
                }
                return ListView.separated(
                  itemCount: rows.length,
                  separatorBuilder: (_, _) => const SizedBox(height: 10),
                  itemBuilder: (context, i) => _EncounterCard(row: rows[i]),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

class _EncounterCard extends StatelessWidget {
  const _EncounterCard({required this.row});

  final Map<String, dynamic> row;

  @override
  Widget build(BuildContext context) {
    final scribe = (row['scribe_draft'] as Map<String, dynamic>?) ?? const {};
    final status = (scribe['status'] as String?) ?? 'none';
    final sections = (scribe['sections'] as Map<String, dynamic>?) ?? const {};
    final type = (row['type'] as String?) ?? 'encounter';
    final patient = (row['patient_id'] as String?) ?? '?';

    final (icon, color, label) = switch (status) {
      'draft' => (Icons.pending_outlined, ClinicTheme.warningAmber, 'Draft awaiting review'),
      'reviewed' => (Icons.task_alt, ClinicTheme.malachite, 'Reviewed'),
      _ => (Icons.graphic_eq_outlined, ClinicTheme.textSecondary, 'No draft yet — ask the agent to draft it'),
    };

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(icon, color: color),
                const SizedBox(width: 10),
                Expanded(
                  child: Text('$type — patient $patient',
                      style: const TextStyle(fontWeight: FontWeight.w700)),
                ),
                Text(label, style: TextStyle(color: color, fontSize: 12)),
              ],
            ),
            if (sections.isNotEmpty) ...[
              const SizedBox(height: 8),
              ...sections.entries.map((e) => Padding(
                    padding: const EdgeInsets.only(bottom: 6),
                    child: Text(
                      '${_capitalize(e.key)}: ${e.value}',
                      style: const TextStyle(color: ClinicTheme.textPrimary, fontSize: 13),
                    ),
                  )),
            ],
            if (status == 'draft') ...[
              const SizedBox(height: 8),
              Align(
                alignment: Alignment.centerRight,
                child: FilledButton.icon(
                  icon: const Icon(Icons.task_alt, size: 18),
                  label: const Text('Mark reviewed'),
                  onPressed: () => _markReviewed(context),
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  Future<void> _markReviewed(BuildContext context) async {
    final uid = Supabase.instance.client.auth.currentUser?.id ?? 'unknown';
    final updated = {
      ...(row['scribe_draft'] as Map<String, dynamic>? ?? const {}),
      'status': 'reviewed',
      'reviewedBy': uid,
      'reviewedAt': DateTime.now().toUtc().toIso8601String(),
    };
    await Supabase.instance.client
        .from('encounters')
        .update({'scribe_draft': updated}).eq('id', row['id'] as String);
  }

  String _capitalize(String s) =>
      s.isEmpty ? s : '${s[0].toUpperCase()}${s.substring(1)}';
}
